<script setup>
import { computed,ref } from 'vue';
import { Link,router,useForm } from '@inertiajs/vue3';
const props=defineProps({branch:Object,ingredients:Object,units:Array,variants:Array,modifierOptions:Array});
const createForm=useForm({name:'',base_unit_id:'',sku:'',description:'',reorder_level:0,is_active:true});
const selectedVariant=ref('');
const recipeForm=useForm({yield_quantity:1,instructions:'',items:[{ingredient_id:'',quantity:1,waste_percent:0}]});
const selectedOption=ref('');
const selectedIngredient=ref('');
const conversionForm=useForm({conversions:[{unit_id:'',to_base_factor:1}]});
const modifierForm=useForm({items:[{ingredient_id:'',quantity_per_option:1}]});
const selectedIngredientData=computed(()=>props.ingredients.data.find(i=>String(i.id)===String(selectedIngredient.value)));
const conversionUnits=computed(()=>props.units.filter(u=>selectedIngredientData.value && u.dimension===selectedIngredientData.value.base_unit?.dimension && Number(u.id)!==Number(selectedIngredientData.value.base_unit_id)));
const selectedVariantData=computed(()=>props.variants.find(v=>String(v.id)===String(selectedVariant.value)));
const selectedOptionData=computed(()=>props.modifierOptions.find(o=>String(o.id)===String(selectedOption.value)));
function submitIngredient(){createForm.post(`/admin/branches/${props.branch.id}/inventory/ingredients`,{preserveScroll:true,onSuccess:()=>createForm.reset()});}
function loadRecipe(){const v=selectedVariantData.value;if(!v)return;recipeForm.yield_quantity=v.yield_quantity||1;recipeForm.items=v.items?.length?v.items.map(i=>({...i})): [{ingredient_id:'',quantity:1,waste_percent:0}];}
function addRecipeItem(){recipeForm.items.push({ingredient_id:'',quantity:1,waste_percent:0});}
function saveRecipe(){recipeForm.put(`/admin/branches/${props.branch.id}/inventory/recipes/${selectedVariant.value}`,{preserveScroll:true});}
function loadConversions(){const i=selectedIngredientData.value;if(!i)return;conversionForm.conversions=i.conversions?.length?i.conversions.map(c=>({unit_id:c.unit_id,to_base_factor:c.to_base_factor})):[{unit_id:'',to_base_factor:1}];}
function addConversion(){conversionForm.conversions.push({unit_id:'',to_base_factor:1});}
function saveConversions(){conversionForm.put(`/admin/branches/${props.branch.id}/inventory/ingredients/${selectedIngredient.value}/conversions`,{preserveScroll:true});}
function loadModifier(){const o=selectedOptionData.value;if(!o)return;modifierForm.items=o.items?.length?o.items.map(i=>({...i})):[{ingredient_id:'',quantity_per_option:1}];}
function addModifierItem(){modifierForm.items.push({ingredient_id:'',quantity_per_option:1});}
function saveModifier(){modifierForm.put(`/admin/branches/${props.branch.id}/inventory/modifier-options/${selectedOption.value}/ingredients`,{preserveScroll:true});}
const qty=(v)=>Number(v||0).toLocaleString('ar-EG',{maximumFractionDigits:3});
</script>
<template>
<main dir="rtl" class="mx-auto max-w-7xl space-y-6 p-4 sm:p-6">
 <header class="flex flex-wrap items-center justify-between gap-3"><div><Link :href="`/admin/branches/${branch.id}/inventory`" class="text-sm font-bold text-amber-700">المخزون</Link><h1 class="mt-1 text-3xl font-black">المكونات والوصفات</h1><p class="mt-1 text-sm text-slate-500">سجل المكونات بوحدة أساس، ثم اربط وصفة كل حجم من المنتج.</p></div></header>
 <form @submit.prevent="submitIngredient" class="grid gap-3 rounded-2xl border bg-white p-5 shadow-sm sm:grid-cols-2 lg:grid-cols-4"><h2 class="font-black sm:col-span-2 lg:col-span-4">إضافة مكون</h2><label class="text-sm font-semibold">اسم المكون<input v-model="createForm.name" required maxlength="150" class="mt-1 w-full rounded-lg border-slate-300" placeholder="لحم بقري"/></label><label class="text-sm font-semibold">وحدة الأساس<select v-model="createForm.base_unit_id" required class="mt-1 w-full rounded-lg border-slate-300"><option value="">اختر الوحدة</option><option v-for="u in units" :key="u.id" :value="u.id">{{u.name}} ({{u.symbol}})</option></select></label><label class="text-sm font-semibold">SKU<input v-model="createForm.sku" class="mt-1 w-full rounded-lg border-slate-300" dir="ltr"/></label><label class="text-sm font-semibold">حد إعادة الطلب<input v-model.number="createForm.reorder_level" type="number" min="0" step="0.001" class="mt-1 w-full rounded-lg border-slate-300"/></label><label class="text-sm font-semibold sm:col-span-2 lg:col-span-3">الوصف<input v-model="createForm.description" class="mt-1 w-full rounded-lg border-slate-300"/></label><div class="flex items-end"><button :disabled="createForm.processing" class="w-full rounded-lg bg-slate-900 px-4 py-2.5 font-bold text-white">حفظ المكون</button></div><p v-if="Object.keys(createForm.errors).length" class="text-sm text-rose-600 sm:col-span-4">{{Object.values(createForm.errors).join(' · ')}}</p></form>
 <section class="overflow-hidden rounded-2xl border bg-white"><div class="border-b p-4"><h2 class="font-black">قائمة المكونات</h2></div><div class="overflow-x-auto"><table class="w-full min-w-[650px] text-right text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="p-3">المكون</th><th class="p-3">SKU</th><th class="p-3">الوحدة</th><th class="p-3">رصيد الفرع</th><th class="p-3">حد الطلب</th></tr></thead><tbody class="divide-y"><tr v-for="i in ingredients.data" :key="i.id"><td class="p-3 font-bold">{{i.name}}</td><td class="p-3" dir="ltr">{{i.sku||'—'}}</td><td class="p-3">{{i.base_unit?.symbol}}</td><td class="p-3">{{qty(i.stocks?.[0]?.on_hand_qty)}} {{i.base_unit?.symbol}}</td><td class="p-3">{{qty(i.reorder_level)}}</td></tr></tbody></table></div><div class="p-4 text-xs text-slate-500">عدد العناصر: {{ingredients.total}}</div></section>
 <section class="grid gap-5 lg:grid-cols-2"><form @submit.prevent="saveRecipe" class="space-y-4 rounded-2xl border bg-white p-5"><div><h2 class="font-black">وصفة المنتج</h2><p class="mt-1 text-xs text-slate-500">الكميات بوحدة الأساس للمكون، وYield يحدد عدد الحصص التي تنتجها الوصفة.</p></div><label class="block text-sm font-semibold">حجم المنتج<select v-model="selectedVariant" @change="loadRecipe" class="mt-1 w-full rounded-lg border-slate-300"><option value="">اختر الحجم</option><option v-for="v in variants" :key="v.id" :value="v.id">{{v.label}}</option></select></label><label class="block text-sm font-semibold">عدد الحصص الناتجة<input v-model.number="recipeForm.yield_quantity" type="number" min="0.001" step="0.001" class="mt-1 w-full rounded-lg border-slate-300"/></label><div v-for="(item,index) in recipeForm.items" :key="index" class="grid grid-cols-3 gap-2 rounded-xl bg-slate-50 p-3"><select v-model="item.ingredient_id" class="col-span-3 rounded-lg border-slate-300 text-sm"><option value="">المكون</option><option v-for="i in ingredients.data" :key="i.id" :value="i.id">{{i.name}} ({{i.base_unit?.symbol}})</option></select><input v-model.number="item.quantity" type="number" min="0.001" step="0.001" placeholder="الكمية" class="rounded-lg border-slate-300 text-sm"/><input v-model.number="item.waste_percent" type="number" min="0" max="100" step="0.01" placeholder="هالك %" class="rounded-lg border-slate-300 text-sm"/><button type="button" @click="recipeForm.items.splice(index,1)" class="rounded-lg border border-rose-200 text-xs font-bold text-rose-700">حذف</button></div><button type="button" @click="addRecipeItem" class="text-sm font-bold text-amber-700">+ إضافة مكون</button><textarea v-model="recipeForm.instructions" rows="2" placeholder="تعليمات التحضير" class="w-full rounded-lg border-slate-300 text-sm"/><button :disabled="!selectedVariant||recipeForm.processing" class="w-full rounded-lg bg-amber-600 px-4 py-2.5 font-bold text-white">حفظ الوصفة</button><p v-if="Object.keys(recipeForm.errors).length" class="text-sm text-rose-600">{{Object.values(recipeForm.errors).join(' · ')}}</p></form>
 <form @submit.prevent="saveModifier" class="space-y-4 rounded-2xl border bg-white p-5"><div><h2 class="font-black">مكونات الإضافات</h2><p class="mt-1 text-xs text-slate-500">اربط اختيار الإضافة باستهلاك المكونات لكل مرة يتم اختيارها.</p></div><label class="block text-sm font-semibold">خيار الإضافة<select v-model="selectedOption" @change="loadModifier" class="mt-1 w-full rounded-lg border-slate-300"><option value="">اختر الإضافة</option><option v-for="o in modifierOptions" :key="o.id" :value="o.id">{{o.label}}</option></select></label><div v-for="(item,index) in modifierForm.items" :key="index" class="grid grid-cols-2 gap-2"><select v-model="item.ingredient_id" class="rounded-lg border-slate-300 text-sm"><option value="">المكون</option><option v-for="i in ingredients.data" :key="i.id" :value="i.id">{{i.name}}</option></select><input v-model.number="item.quantity_per_option" type="number" min="0.001" step="0.001" class="rounded-lg border-slate-300 text-sm" placeholder="الكمية لكل اختيار"/></div><button type="button" @click="addModifierItem" class="text-sm font-bold text-amber-700">+ إضافة مكون</button><button :disabled="!selectedOption||modifierForm.processing" class="w-full rounded-lg bg-slate-900 px-4 py-2.5 font-bold text-white">حفظ مكونات الإضافة</button><p v-if="Object.keys(modifierForm.errors).length" class="text-sm text-rose-600">{{Object.values(modifierForm.errors).join(' · ')}}</p></form><form @submit.prevent="saveConversions" class="space-y-4 rounded-2xl border bg-white p-5"><div><h2 class="font-black">تحويل وحدات المكون</h2><p class="mt-1 text-xs text-slate-500">مثال: 1 كيلوجرام = 1000 جرام. يتم حفظ معامل التحويل إلى وحدة الأساس.</p></div><label class="block text-sm font-semibold">المكون<select v-model="selectedIngredient" @change="loadConversions" class="mt-1 w-full rounded-lg border-slate-300"><option value="">اختر المكون</option><option v-for="i in ingredients.data" :key="i.id" :value="i.id">{{i.name}} · {{i.base_unit?.symbol}}</option></select></label><div v-for="(c,index) in conversionForm.conversions" :key="index" class="grid grid-cols-2 gap-2"><select v-model="c.unit_id" class="rounded-lg border-slate-300 text-sm"><option value="">وحدة التحويل</option><option v-for="u in conversionUnits" :key="u.id" :value="u.id">{{u.name}} ({{u.symbol}})</option></select><input v-model.number="c.to_base_factor" type="number" min="0.000001" step="0.000001" placeholder="معامل التحويل" class="rounded-lg border-slate-300 text-sm"/></div><button type="button" @click="addConversion" class="text-sm font-bold text-amber-700">+ إضافة وحدة</button><button :disabled="!selectedIngredient||conversionForm.processing" class="w-full rounded-lg bg-slate-900 px-4 py-2.5 font-bold text-white">حفظ التحويلات</button></form>
</section>
</main>
</template>
